package com.example.domain.model.i18n

internal object DuaAr3 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_q_atina_ma_waadtana" to DuaText("آتنا ما وعدتنا", "ربنا وآتنا ما وعدتنا على رسلك ولا تخزنا يوم القيامة ۗ إنك لا تخلف الميعاد", "الاستعاذة من خزي يوم القيامة", "طلب الكرامة في الآخرة."),
        "dua_q_atmim_nurana" to DuaText("أتمم لنا نورنا", "ربنا أتمم لنا نورنا واغفر لنا ۖ إنك على كل شيء قدير", "دعاء المؤمنين يوم القيامة", "طلب النور على الصراط."),
        "dua_q_do_not_make_us_trial" to DuaText("لا تجعلنا فتنة للذين كفروا", "Hazrat Ibrahim (AS) aur unke saathiyon ki dua.", "دعاء إبراهيم عليه السلام وأصحابه", "دعاء المغفرة والعزة والحكمة."),
        "dua_q_hab_li_hukman" to DuaText("دعاء إبراهيم عليه السلام: الحكمة والجنة", "رب هب لي حكما وألحقني بالصالحين (٨٣) واجعل لي لسان صدق في الآخرين (٨٤) واجعلني من ورثة جنة النعيم (٨٥)", "طلب الحكمة وصحبة الصالحين ودخول الجنة", "دعاء إبراهيم عليه السلام الجامع."),
        "dua_q_hab_li_salihin" to DuaText("دعاء إبراهيم عليه السلام لولد صالح", "رب هب لي من الصالحين", "طلب الولد الصالح", "استجيبت له فرزق إسماعيل عليه السلام."),
        "dua_q_hawariyyun" to DuaText("دعاء الحواريين: اكتبنا مع الشاهدين", "ربنا آمنا بما أنزلت واتبعنا الرسول فاكتبنا مع الشاهدين", "الثبات على الإيمان واتباع الرسول", "دعاء حواريي عيسى عليه السلام."),
        "dua_q_iftah_baynana" to DuaText("دعاء شعيب عليه السلام: افتح بيننا", "ربنا افتح بيننا وبين قومنا بالحق وأنت خير الفاتحين", "طلب الفصل بين الحق والباطل", "دعاء شعيب عليه السلام عندما كذّبته قومه."),
        "dua_q_ihkum_bil_haqq" to DuaText("ربي احكم بالحق", "رب احكم بالحق ۗ وربنا الرحمن المستعان على ما تصفون", "عند مواجهة الاتهامات الباطلة", "دعاء علّمه الله للنبي ﷺ."),
        "dua_q_ikhwanina" to DuaText("لإخواننا الذين سبقونا بالإيمان", "ربنا اغفر لنا ولإخواننا الذين سبقونا بالإيمان ولا تجعل في قلوبنا غلا للذين آمنوا ربنا إنك رءوف رحيم", "للمؤمنين السابقين وسلامة القلب", "دعاء للصحابة والمؤمنين السابقين."),
        "dua_q_israfana" to DuaText("اغفر لنا إسرافنا في أمرنا", "ربنا اغفر لنا ذنوبنا وإسرافنا في أمرنا وثبت أقدامنا وانصرنا على القوم الكافرين", "دعاء أصحاب الأنبياء السابقين", "دعاء الثبات والمغفرة."),
        "dua_q_isrif_jahannam" to DuaText("اصرف عنا عذاب جهنم", "ربنا اصرف عنا عذاب جهنم ۖ إن عذابها كان غراما (٦٥) إنها ساءت مستقرا ومقاما (٦٦)", "دعاء عباد الرحمن", "دعاء قرآني للنجاة من جهنم."),
        "dua_q_jamiun_nas" to DuaText("إنك جامع الناس ليوم لا ريب فيه", "ربنا إنك جامع الناس ليوم لا ريب فيه ۚ إن الله لا يخلف الميعاد", "إقرار بيوم القيامة", "دعاء الراسخين في العلم."),
        "dua_q_khayrun_hafiza" to DuaText("الله خير حافظًا", "فالله خير حافظا ۖ وهو أرحم الراحمين", "عند توديع الأبناء أو الأحباب في سفر", "قالها يعقوب عليه السلام عند توديع ابنه لله."),
        "dua_q_la_akuna_zahiran" to DuaText("دعاء موسى عليه السلام: لن أكون ظهيرًا للمجرمين", "رب بما أنعمت علي فلن أكون ظهيرا للمجرمين", "شكر النعمة والعزم على عدم معاونة المجرمين", "عهد موسى عليه السلام بعد التوبة."),
        "dua_q_la_tadharni_fardan" to DuaText("دعاء زكريا عليه السلام: لا تذرني فردًا", "رب لا تذرني فردا وأنت خير الوارثين", "طلب الولد", "استجاب الله فرزقه يحيى عليه السلام."),
        "dua_q_la_tajalna_fitnah" to DuaText("لا تجعلنا فتنة للقوم الظالمين", "على الله توكلنا ربنا لا تجعلنا فتنة للقوم الظالمين (٨٥) ونجنا برحمتك من القوم الكافرين (٨٦)", "دعاء قوم موسى عليه السلام", "دعاء النجاة من الظلم والظالمين."),
        "dua_q_la_tajalna_zalimin" to DuaText("لا تجعلنا مع القوم الظالمين", "ربنا لا تجعلنا مع القوم الظالمين", "دعاء أهل الأعراف", "الاستعاذة من عاقبة الظالمين."),
        "dua_q_la_tukhzini" to DuaText("دعاء إبراهيم عليه السلام: لا تخزني", "ولا تخزني يوم يبعثون", "الاستعاذة من خزي يوم القيامة", "دعاء إبراهيم عليه السلام للآخرة."),
        "dua_q_lut_najjini_ahli" to DuaText("دعاء لوط عليه السلام: نجني وأهلي", "رب نجني وأهلي مما يعملون", "حفظ الأهل من بيئة الفساد", "حفظ الأهل من السوء."),
        "dua_q_lut_unsurni" to DuaText("دعاء لوط عليه السلام: انصرني على المفسدين", "رب انصرني على القوم المفسدين", "طلب النصر على أهل الفساد", "دعاء الثابتين على الحق."),
        "dua_q_maash_shahidin" to DuaText("فاكتبنا مع الشاهدين", "ربنا آمنا فاكتبنا مع الشاهدين", "دعاء من آمن بعد معرفة الحق", "دعاء قبول الإيمان."),
        "dua_q_ma_khalaqta_batila" to DuaText("التفكر في الخلق", "ربنا ما خلقت هذا باطلا سبحانك فقنا عذاب النار", "دعاء المتفكرين في خلق السماوات والأرض", "دعاء أولي الألباب."),
        "dua_q_mudkhala_sidq" to DuaText("مدخل صدق ومخرج صدق", "رب أدخلني مدخل صدق وأخرجني مخرج صدق واجعل لي من لدنك سلطانا نصيرا", "قبل الدخول في أمر جديد أو بيت أو مكان", "علّمه الله للنبي ﷺ عند الهجرة."),
        "dua_q_munzalan_mubarakan" to DuaText("أنزلني منزلًا مباركًا", "رب أنزلني منزلا مباركا وأنت خير المنزلين", "عند الانتقال إلى بيت جديد أو النزول في مكان", "دعاء البركة في المكان الجديد."),
        "dua_q_musa_li_akhi" to DuaText("دعاء موسى عليه السلام: اغفر لي ولأخي", "رب اغفر لي ولأخي وأدخلنا في رحمتك ۖ وأنت أرحم الراحمين", "لنفسه ولأخيه أو أقاربه", "دعاء موسى عليه السلام لهارون عليه السلام."),
        "dua_q_musa_najjini" to DuaText("دعاء موسى عليه السلام: نجني من القوم الظالمين", "رب نجني من القوم الظالمين", "عند الخوف من الظالمين", "دعاء موسى عليه السلام عند خروجه من مصر."),
        "dua_q_musa_zalamtu" to DuaText("دعاء موسى عليه السلام: إني ظلمت نفسي", "رب إني ظلمت نفسي فاغفر لي", "التوبة الفورية عند الخطأ", "غفر الله لموسى عليه السلام."),
        "dua_q_muslimayni_laka" to DuaText("دعاء إبراهيم وإسماعيل: اجعلنا مسلمين لك", "ربنا واجعلنا مسلمين لك ومن ذريتنا أمة مسلمة لك وأرنا مناسكنا وتب علينا ۖ إنك أنت التواب الرحيم", "دعاء لنفسه وذريته بالطاعة", "دعاء عند بناء الكعبة."),
        "dua_q_not_among_wrongdoers" to DuaText("لا تجعلني في القوم الظالمين", "Allah se zulm karne walon se alag rakhne ki dua.", "دعاء يطلب البعد عن الظالمين", "دعاء يطلب البعد عن أهل الظلم."),
        "dua_q_nuh_ma_laysa_li" to DuaText("دعاء نوح عليه السلام بالمغفرة", "رب إني أعوذ بك أن أسألك ما ليس لي به علم ۖ وإلا تغفر لي وترحمني أكن من الخاسرين", "دعاء توبة نوح عليه السلام", "أدب السؤال في الدعاء."),
        "dua_q_nuh_unsurni" to DuaText("دعاء نوح عليه السلام: انصرني بما كذبون", "رب انصرني بما كذبون", "عندما يكذّب الناس ولا يقبلون الحق", "دعاء نوح عليه السلام الذي استجيب."),
        "dua_q_sami_na_munadiyan" to DuaText("سمعنا مناديًا ينادي للإيمان", "ربنا إننا سمعنا مناديا ينادي للإيمان أن آمنوا بربكم فآمنا ۚ ربنا فاغفر لنا ذنوبنا وكفر عنا سيئاتنا وتوفنا مع الأبرار", "دعاء الموت مع الأبرار", "دعاء المغفرة وحسن الخاتمة."),
        "dua_q_sawa_as_sabil" to DuaText("دعاء موسى عليه السلام: يهديني سواء السبيل", "عسى ربي أن يهديني سواء السبيل", "عند السفر أو سلوك طريق مجهول", "قالها موسى عليه السلام متوجهًا إلى مدين."),
        "dua_q_sulaiman_awzini" to DuaText("دعاء سليمان عليه السلام للشكر", "رب أوزعني أن أشكر نعمتك التي أنعمت علي وعلى والدي وأن أعمل صالحا ترضاه وأدخلني برحمتك في عبادك الصالحين", "التوفيق لشكر النعمة", "دعاء سليمان عليه السلام للشكر."),
        "dua_q_tawaffana_muslimin" to DuaText("أفرغ علينا صبرًا وتوفنا مسلمين", "ربنا أفرغ علينا صبرا وتوفنا مسلمين", "دعاء سحرة فرعون حين آمنوا", "الصبر عند الابتلاء والختم بالإيمان."),
        "dua_q_ufawwidu_amri" to DuaText("أفوض أمري إلى الله", "وأفوض أمري إلى الله ۚ إن الله بصير بالعباد", "عند معارضة الناس وتفويض الأمر لله", "قول مؤمن آل فرعون، فحفظه الله من كيدهم."),
        "dua_q_wasita_kulla_shay" to DuaText("دعاء الملائكة حملة العرش", "ربنا وسعت كل شيء رحمة وعلما فاغفر للذين تابوا واتبعوا سبيلك وقهم عذاب الجحيم", "دعاء الملائكة حملة العرش للمؤمنين", "بنية الاشتراك في دعاء الملائكة."),
        "dua_rabbana_hab_lana_rahmah" to DuaText("طلب الرشد في الأمر (أصحاب الكهف)", "ربنا آتنا من لدنك رحمة وهيئ لنا من أمرنا رشدا", "دعاء أصحاب الكهف", "الاستهداء في القرارات والمواقف الصعبة."),
        "dua_rabbana_innana_amanna" to DuaText("المغفرة والنجاة من النار", "ربنا إننا آمنا فاغفر لنا ذنوبنا وقنا عذاب النار", "دعاء قرآني", "دعاء ذكره الله عن صفة المتقين."),
        "dua_rabba_jibrail" to DuaText("اهدني لما اختلف فيه من الحق", "اللهم رب جبرائيل وميكائيل وإسرافيل، فاطر السماوات والأرض، عالم الغيب والشهادة، أنت تحكم بين عبادك فيما كانوا فيه يختلفون، اهدني لما اختلف فيه من الحق بإذنك، إنك تهدي من تشاء إلى صراط مستقيم", "في بداية التهجد — طلب الهداية عند الاختلاف", "كان النبي ﷺ يفتتح صلاة الليل بهذا الدعاء."),
        "dua_rabbighfir_tub_alayya" to DuaText("اغفر لي وتب علي", "رب اغفر لي وتب علي، إنك أنت التواب الرحيم", "مائة مرة في المجلس الواحد — عادة النبي ﷺ", "سمعه الصحابة يقولها مائة مرة في المجلس."),
        "dua_rabbi_ainni" to DuaText("ربي أعني ولا تعن علي", "رب أعني ولا تعن علي، وانصرني ولا تنصر علي، وامكر لي ولا تمكر علي، واهدني ويسر الهدى لي، وانصرني على من بغى علي", "جزء من دعاء النبي ﷺ الجامع", "دعاء جامع لكل عون في الدين والدنيا."),
        "dua_rafiq_ala" to DuaText("دعاء المحتضر", "اللهم اغفر لي وارحمني، وألحقني بالرفيق الأعلى", "آخر دعاء النبي ﷺ — دعاء المريض لنفسه", "دعا بها النبي ﷺ عند وفاته."),
        "dua_rahmataka_arju" to DuaText("رحمتك أرجو", "اللهم رحمتك أرجو، فلا تكلني إلى نفسي طرفة عين، وأصلح لي شأني كله، لا إله إلا أنت", "دعاء المكروب", "دعاء النبي ﷺ للمكروب."),
        "dua_rain" to DuaText("عند نزول المطر", "اللهم صيبا نافعا", "عند هطول المطر", "وقت نزول المطر من أوقات إجابة الدعاء."),
        "dua_reply_ahl_kitab_salam" to DuaText("الرد على سلام أهل الكتاب", "وعليكم", "إذا سلّم عليك أهل الكتاب", "أمر النبي ﷺ."),
        "dua_rising_ruku_mil" to DuaText("بعد الركوع: حمد يملأ السماوات", "ربنا لك الحمد، ملء السماوات وملء الأرض، وملء ما شئت من شيء بعد", "بعد الرفع من الركوع", "كان النبي ﷺ يقولها بعد الرفع من الركوع."),
        "dua_rooster_donkey" to DuaText("سماع صياح الديك أو نهيق الحمار", "اللهم إني أسألك من فضلك — أعوذ بالله من الشيطان الرجيم", "عند صياح الديك يُسأل الفضل، وعند نهيق الحمار يُستعاذ من الشيطان", "الديك يرى ملكًا والحمار يرى شيطانًا."),
        "dua_ruku_laka_raka_tu" to DuaText("في الركوع: لك ركعت", "اللهم لك ركعت، وبك آمنت، ولك أسلمت، خشع لك سمعي وبصري ومخي وعظمي وعصبي", "في الركوع", "كان النبي ﷺ يقولها في ركوعه."),
        "dua_ruku_sujood_subhanaka" to DuaText("سبحانك اللهم ربنا وبحمدك", "سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي", "في الركوع والسجود", "روت عائشة رضي الله عنها إكثار النبي ﷺ منها."),
        "dua_sabr" to DuaText("الصبر والثبات", "ربنا أفرغ علينا صبرا وثبت أقدامنا وانصرنا على القوم الكافرين", "عند الشدائد والمواجهة", "دعاء جند طالوت."),
        "dua_safa_marwa" to DuaText("على الصفا والمروة", "لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، لا إله إلا الله وحده، أنجز وعده، ونصر عبده، وهزم الأحزاب وحده", "عند الصعود على الصفا مستقبل القبلة (ثلاث مرات)", "ذكر النبي ﷺ على الصفا والمروة."),
        "dua_sajdah_tilawah" to DuaText("سجدة التلاوة", "سجد وجهي للذي خلقه، وشق سمعه وبصره، بحوله وقوته", "في سجدة التلاوة", "كان النبي ﷺ يقولها في سجدة تلاوة الليل."),
        "dua_seeing_clouds" to DuaText("رؤية السحاب الداكن", "اللهم إني أعوذ بك من شرها", "عند رؤية الغيوم", "كان النبي ﷺ يترك عمله عند رؤية السحاب ويدعو."),
        "dua_seeing_muslim_smile" to DuaText("السلام", "السلام عليكم ورحمة الله وبركاته", "عند لقاء المسلم", "بإتمام السلام يحصل على ثلاثين حسنة."),
        "dua_sell_buy_debt_repaid" to DuaText("عند سداد الدين", "بارك الله لك في أهلك ومالك", "عند رد الدين لصاحبه", "جزاء القرض الشكر والوفاء."),
        "dua_shaitan_hamazat" to DuaText("الاستعاذة من نزغات الشياطين", "رب أعوذ بك من همزات الشياطين (٩٧) وأعوذ بك رب أن يحضرون (٩٨)", "الاستعاذة من وساوس الشيطان", "استعاذة قرآنية."),
        "dua_sharri_ma_amiltu" to DuaText("الاستعاذة من شر ما عملت", "اللهم إني أعوذ بك من شر ما عملت، ومن شر ما لم أعمل", "روته عائشة رضي الله عنها عن النبي ﷺ", "الحفظ من شر ما فعل وما لم يفعل."),
        "dua_sharri_sami" to DuaText("الاستعاذة من شر الحواس", "اللهم إني أعوذ بك من شر سمعي، ومن شر بصري، ومن شر لساني، ومن شر قلبي، ومن شر منيي", "علّمها النبي ﷺ لشكل بن حميد رضي الله عنه", "حفظ الجوارح والنفس من الذنب."),
        "dua_shirk_protection" to DuaText("الحفظ من الشرك الخفي", "اللهم إني أعوذ بك أن أشرك بك وأنا أعلم، وأستغفرك لما لا أعلم", "الحفظ من الرياء والشرك الخفي", "الشرك الخفي أخفى من دبيب النملة."),
        "dua_slaughtering" to DuaText("عند ذبح الحيوان", "بسم الله والله أكبر", "عند الذبح أو التضحية", "سمّى النبي ﷺ وكبّر عند الأضحية."),
        "dua_sleep_atamana" to DuaText("الشكر قبل النوم", "الحمد لله الذي أطعمنا وسقانا، وكفانا وآوانا، فكم ممن لا كافي له ولا مؤوي", "عند الأخذ إلى الفراش", "كان النبي ﷺ يقولها عند أخذه مضجعه."),
        "dua_sleep_fear" to DuaText("الخوف أو الفزع في النوم", "أعوذ بكلمات الله التامة من غضبه وعقابه، وشر عباده، ومن همزات الشياطين وأن يحضرون", "عند الفزع أو الخوف في النوم", "من قالها لم يضره ذلك."),
        "dua_sleep_khalaqta_nafsi" to DuaText("أنت خلقت نفسي", "اللهم خلقت نفسي وأنت توفاها، لك مماتها ومحياها، إن أحييتها فاحفظها، وإن أمتها فاغفر لها، اللهم إني أسألك العافية", "قبل النوم — رواية ابن عمر رضي الله عنهما", "أمر النبي ﷺ بقولها عند النوم."),
        "dua_sleep_rabbas_samawat" to DuaText("رب السماوات: اقض عنا الدين", "اللهم رب السماوات ورب الأرض ورب العرش العظيم، ربنا ورب كل شيء، فالق الحب والنوى، ومنزل التوراة والإنجيل والفرقان، أعوذ بك من شر كل شيء أنت آخذ بناصيته، اللهم أنت الأول فليس قبلك شيء، وأنت الآخر فليس بعدك شيء، وأنت الظاهر فليس فوقك شيء، وأنت الباطن فليس دونك شيء، اقض عنا الدين وأغننا من الفقر", "قبل النوم على الجانب الأيمن — علّمها النبي ﷺ لفاطمة رضي الله عنها", "دعاء قضاء الدين والغنى من الفقر."),
        "dua_sleep_wadatu_janbi" to DuaText("باسمك وضعت جنبي", "باسمك ربي وضعت جنبي، وبك أرفعه، إن أمسكت نفسي فارحمها، وإن أرسلتها فاحفظها بما تحفظ به عبادك الصالحين", "بعد فرش الفراش والاستلقاء", "تسليم الروح لله قبل النوم."),
        "dua_sneezing" to DuaText("العطاس", "الحمد لله — يرحمك الله — يهديكم الله ويصلح بالكم", "عند العطاس؛ يقول السامع 'يرحمك الله' ثم يرد العاطس", "من حقوق المسلم على المسلم."),
        "dua_something_liked" to DuaText("عند رؤية ما يُعجب (دفعًا للعين)", "ما شاء الله، اللهم بارك عليه", "عند رؤية شيء حسن لأحد فادعُ له بالبركة", "الدعاء بالبركة يمنع إصابة العين."),
        "dua_subbuhun_quddus" to DuaText("سبوح قدوس (الركوع والسجود)", "سبوح قدوس رب الملائكة والروح", "في الركوع والسجود", "كان النبي ﷺ يقولها في ركوعه وسجوده."),
        "dua_sujood_dhanbi_kullah" to DuaText("في السجود: اغفر لي ذنبي كله", "اللهم اغفر لي ذنبي كله، دقه وجله، وأوله وآخره، وعلانيته وسره", "في السجود", "السجود موضع إجابة الدعاء."),
        "dua_sujood_laka_sajadtu" to DuaText("في السجود: لك سجدت", "اللهم لك سجدت، وبك آمنت، ولك أسلمت، سجد وجهي للذي خلقه وصوره، وشق سمعه وبصره، تبارك الله أحسن الخالقين", "في السجود", "كان النبي ﷺ يقولها في سجوده."),
        "dua_sujood_ridaka" to DuaText("الاستعاذة برضاك من سخطك", "اللهم إني أعوذ برضاك من سخطك، وبمعافاتك من عقوبتك، وأعوذ بك منك، لا أحصي ثناء عليك، أنت كما أثنيت على نفسك", "في السجود — سمعتها عائشة رضي الله عنها من النبي ﷺ", "دعاء النبي ﷺ في سجوده."),
        "dua_tahajjud_nur" to DuaText("افتتاح صلاة التهجد", "اللهم لك الحمد، أنت قيم السماوات والأرض ومن فيهن، ولك الحمد، أنت نور السماوات والأرض ومن فيهن، ولك الحمد، أنت الحق، ووعدك الحق، ولقاؤك حق، وقولك حق، والجنة حق، والنار حق، والنبيون حق، ومحمد ﷺ حق، والساعة حق", "عند بدء صلاة الليل (التهجد)", "كان النبي ﷺ يفتتح تهجده بها."),
        "dua_tahleel_10_fajr" to DuaText("عشر تهليلات بعد الفجر والمغرب", "لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، يحيي ويميت، وهو على كل شيء قدير", "بعد الفجر، قبل ثني الرجلين والكلام، عشر مرات", "عشر حسنات وعشر سيئات تُمحى وعشر درجات وحفظ من الشيطان طوال اليوم."),
        "dua_takbeer_tashreeq" to DuaText("تكبير التشريق", "الله أكبر الله أكبر، لا إله إلا الله، والله أكبر، الله أكبر ولله الحمد", "من فجر ٩ ذي الحجة إلى عصر ١٣ ذي الحجة بعد كل صلاة فرض", "مروي عن علي وابن مسعود رضي الله عنهما، واجب عند الأحناف."),
        "dua_talbiyah" to DuaText("التلبية", "لبيك اللهم لبيك، لبيك لا شريك لك لبيك، إن الحمد والنعمة لك والملك، لا شريك لك", "بعد الإحرام بصوت مرتفع", "شعار الحج والعمرة."),
        "dua_talqeen" to DuaText("تلقين المحتضر", "لا إله إلا الله", "عند من حضره الموت يُقال له كلمة التوحيد", "من كان آخر كلامه 'لا إله إلا الله' دخل الجنة."),
        "dua_tashahhud" to DuaText("التشهد", "التحيات لله والصلوات والطيبات، السلام عليك أيها النبي ورحمة الله وبركاته، السلام علينا وعلى عباد الله الصالحين، أشهد أن لا إله إلا الله، وأشهد أن محمدا عبده ورسوله", "في كل قعدة — رواية ابن مسعود رضي الله عنه", "كان النبي ﷺ يعلمها كسورة من القرآن."),
        "dua_thabbitni_hadiyan" to DuaText("ثبّتني واجعلني هاديًا مهديًا", "اللهم ثبتني، واجعلني هاديا مهديا", "دعا بها النبي ﷺ لجرير رضي الله عنه", "الدعاء الأصلي لجرير رضي الله عنه بلفظ 'ثبته'."),
        "dua_thanking" to DuaText("شكر من أحسن إليك", "جزاك الله خيرا", "عند تلقي معروف من أحد", "من قالها فقد أبلغ في الثناء."),
        "dua_thunder" to DuaText("عند سماع الرعد", "سبحان الذي يسبح الرعد بحمده والملائكة من خيفته", "عند سماع صوت الرعد — عمل عبد الله بن الزبير رضي الله عنه", "مأخوذ من سورة الرعد (١٣:١٣)."),
        "dua_toilet_enter" to DuaText("دخول الخلاء", "بسم الله، اللهم إني أعوذ بك من الخبث والخبائث", "قبل دخول الخلاء بالقدم اليسرى", "البسملة حاجز بين أعين الجن وعورات بني آدم."),
        "dua_toilet_exit" to DuaText("الخروج من الخلاء", "غفرانك", "عند الخروج من الخلاء بالقدم اليمنى", "كان النبي ﷺ يقولها عند خروجه من الخلاء."),
        "dua_traveller_sahar" to DuaText("دعاء المسافر قبل الفجر", "سمع سامع بحمد الله وحسن بلائه علينا، ربنا صاحبنا وأفضل علينا، عائذا بالله من النار", "عند السحر في السفر", "كان النبي ﷺ يقولها في السحر أثناء السفر."),
        "dua_traveller_to_resident" to DuaText("المسافر لمن يودعهم", "أستودعكم الله الذي لا تضيع ودائعه", "عند توديع المسافر لأهله", "حفظ الأهل بوديعة الله."),
        "dua_two_light_words" to DuaText("كلمتان خفيفتان على اللسان", "سبحان الله وبحمده، سبحان الله العظيم", "خفيفتان على اللسان ثقيلتان في الميزان", "حبيبتان إلى الرحمن، خفيفتان على اللسان، ثقيلتان في الميزان."),
        "dua_undressing" to DuaText("عند خلع الثياب", "بسم الله", "عند خلع الثياب", "حاجز بين أعين الجن وعورة الإنسان."),
        "dua_useless_knowledge" to DuaText("الاستعاذة من علم لا ينفع", "اللهم إني أعوذ بك من علم لا ينفع، ومن قلب لا يخشع، ومن نفس لا تشبع، ومن دعوة لا يستجاب لها", "الاستعاذة من علم لا ينفع وقلب لا يخشع", "دعاء استعاذة نبوي."),
        "dua_vehicle_stumbles" to DuaText("عند تعثر المركوب", "بسم الله", "إذا تعثرت الدابة، بدلًا من لعن الشيطان", "بقول البسملة يصغر الشيطان كالذباب."),
        "dua_visiting_graves" to DuaText("زيارة القبور", "السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم للاحقون، أسأل الله لنا ولكم العافية", "عند دخول المقبرة", "زيارة القبور تذكّر بالموت والآخرة."),
        "dua_waking_afani" to DuaText("الاستيقاظ: رد الله عليّ روحي", "الحمد لله الذي عافاني في جسدي، ورد علي روحي، وأذن لي بذكره", "عند الاستيقاظ", "شكر على يوم جديد."),
        "dua_waswasa_salah" to DuaText("الوسوسة في الصلاة (خنزب)", "أعوذ بالله من الشيطان الرجيم", "عند الوسوسة في الصلاة، يستعيذ بالله وينفث يسارًا ثلاثًا", "فعلها عثمان بن أبي العاص رضي الله عنه فذهب عنه الوسواس."),
        "dua_wedding_night" to DuaText("للعروس بعد النكاح", "اللهم إني أسألك خيرها وخير ما جبلتها عليه، وأعوذ بك من شرها وشر ما جبلتها عليه", "بعد النكاح، بوضع اليد على ناصيتها", "تعليم النبي ﷺ لبركة الزواج."),
        "dua_wind" to DuaText("عند هبوب الريح", "اللهم إني أسألك خيرها، وخير ما فيها، وخير ما أرسلت به، وأعوذ بك من شرها، وشر ما فيها، وشر ما أرسلت به", "عند هبوب الريح الشديدة", "كان النبي ﷺ يقولها عند اشتداد الريح."),
        "dua_yamani_hajar" to DuaText("بين الركن اليماني والحجر الأسود", "ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار", "في الطواف بين الركن اليماني والحجر الأسود", "كان النبي ﷺ يقولها في هذا الموضع من الطواف."),
        "dua_muawwidhat" to DuaText("المعوذات الثلاث", "بسم الله الرحمن الرحيم قل هو الله أحد، الله الصمد، لم يلد ولم يولد، ولم يكن له كفوا أحد. بسم الله الرحمن الرحيم قل أعوذ برب الفلق من شر ما خلق، ومن شر غاسق إذا وقب، ومن شر النفاثات في العقد، ومن شر حاسد إذا حسد. بسم الله الرحمن الرحيم قل أعوذ برب الناس، ملك الناس، إله الناس، من شر الوسواس الخناس، الذي يوسوس في صدور الناس، من الجنة والناس.", "صباحًا ومساءً ثلاث ثلاث مرات، وقبل النوم بالنفث في الكفين ومسح الجسد", "قراءتها ثلاثًا صباحًا ومساءً تكفي من كل شيء."),
        "dua_ya_dhal_jalal" to DuaText("يا ذا الجلال والإكرام", "يا ذا الجلال والإكرام", "ألزموا هذا الدعاء — أمر النبي ﷺ", "أمر النبي ﷺ بلزوم 'يا ذا الجلال والإكرام'."),
        "dua_zamzam" to DuaText("شرب ماء زمزم", "اللهم إني أسألك علما نافعا، ورزقا واسعا، وشفاء من كل داء", "عند شرب ماء زمزم ادعُ بما شئت", "ماء زمزم لما شرب له."),
        "dua_zawal_nimah" to DuaText("الاستعاذة من زوال النعمة", "اللهم إني أعوذ بك من زوال نعمتك، وتحول عافيتك، وفجاءة نقمتك، وجميع سخطك", "الاستعاذة من زوال النعمة وتحول العافية والنقمة المفاجئة", "دعاء نبوي."),
        "dua_zawwadakallah" to DuaText("زودك الله التقوى", "زودك الله التقوى، وغفر ذنبك، ويسر لك الخير حيثما كنت", "عند توديع المسافر", "أعطاها النبي ﷺ للمسافر."),
    )
}
